{
  "findings": [
    {
      "check_id": "CKV_AWS_264",
      "title": "Ensure that AMI is not publicly exposed",
      "resource": "aws_ami.pass",
      "severity": "MEDIUM",
      "explanation": "The AMI is not explicitly set to be private, which could lead to unintended public exposure."
    }
  ],
  "patched_code": "resource "aws_ami" "pass" {
  name                = "terraform-example"
  virtualization_type = "hvm"
  root_device_name    = "/dev/xvda1"

  ebs_block_device {
    device_name = "/dev/xvda1"
    volume_size = 8
    snapshot_id = "someid"
  }

  ebs_block_device {
    device_name = "/dev/xvda2"
    volume_size = 8
    encrypted   = true
  }

  lifecycle {
    create_before_destroy = true
  }

  # Added to prevent public exposure
  image_location = "some-location"
}

# Added resource to manage AMI launch permissions
resource "aws_ami_launch_permission" "pass" {
  image_id   = aws_ami.pass.id
  group      = "all"
  depends_on = [aws_ami.pass]
  count      = 0 # Set to 0 to not make it public
}",
  "fix_summary": "Added a new aws_ami_launch_permission resource with count set to 0 to prevent public exposure of the AMI by default."
}
